// Okuma zinciri hata verdiyse: dosya gerçekten YOKSA boş listeyle devam edilir,
// ama dosya bozuk/erişilemez ise çalışma durdurulur — aksi hâlde liste boş
// sanılıp üzerine yazılır ve veriler kaybolur.
const _dosyaKontrol = (okuNode, cikarNode, dosya) => {
  const okuHata = $(okuNode).first().json.error;
  const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
  if (/ENOENT|no such file|not found/i.test(okuMesaj)) return; // dosya henüz oluşmamış
  const cikarHata = $(cikarNode).first().json.error;
  if (okuHata || cikarHata) {
    const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
    throw new Error(dosya + ' okunamadı; takip geçmişi korunsun diye durduruldu → ' + m);
  }
};
_dosyaKontrol('Sayfaları Oku', 'Sayfaları Çıkar', 'sayfa-takibi.json');


// Takip listesindeki her sayfa için bir çıktı üretir.
const j = $('Sayfaları Çıkar').first().json || {};
const d = (j.data && j.data.sayfalar) || [];
const sayfalar = (Array.isArray(d) ? d : []).filter(
  (s) => s && typeof s.url === 'string' && /^https?:\/\//i.test(s.url));

if (sayfalar.length === 0) {
  throw new Error('sayfa-takibi.json içinde geçerli sayfa yok. Örnek için local-files/sayfa-takibi.ornek.json dosyasına bakın.');
}

return sayfalar.map((s) => ({ json: {
  ...s,
  ad: String(s.ad || s.url),
  // Seçici verilmezse sayfanın gövdesi izlenir.
  secici: String(s.secici || 'body').trim() || 'body',
} }));

// Her sayfanın içeriğini önceki turla karşılaştırır.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));

// Kısa ve hızlı bir metin parmak izi (FNV-1a). Şifreleme değil, yalnızca
// "değişti mi?" sorusunu ucuza cevaplamak için.
const parmakIzi = (metin) => {
  let h = 0x811c9dc5;
  for (let i = 0; i < metin.length; i++) {
    h ^= metin.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h.toString(16).padStart(8, '0') + ':' + metin.length;
};

const sayfalar = $('Sayfaları Aç').all().map((x) => ({ ...x.json }));
const sonuclar = $input.all();
const simdi = new Date().toISOString();

const degisenler = [];
const hatalar = [];
const yeniListe = [];

sayfalar.forEach((s, i) => {
  const cikti = (sonuclar[i] && sonuclar[i].json) || {}; // sıra korunur
  const indirme = $('Sayfayı İndir').all()[i];
  const indirmeHata = indirme && indirme.json && indirme.json.error;

  const temiz = { ...s };
  delete temiz.sonHata;
  temiz.sonKontrol = simdi;

  if (indirmeHata || cikti.error) {
    const ham = String(
      (indirmeHata && (indirmeHata.message || indirmeHata)) ||
      (cikti.error && (cikti.error.message || cikti.error)) || 'bilinmeyen hata');
    temiz.sonHata = ham.slice(0, 200);
    hatalar.push(s.ad + ': ' + temiz.sonHata);
    yeniListe.push(temiz); // önceki parmak izi korunur, veri kaybolmaz
    return;
  }

  const metin = String(cikti.icerik || '').replace(/\s+/g, ' ').trim();
  if (!metin) {
    temiz.sonHata = 'Seçici (' + s.secici + ') hiçbir metin döndürmedi.';
    hatalar.push(s.ad + ': ' + temiz.sonHata);
    yeniListe.push(temiz);
    return;
  }

  const iz = parmakIzi(metin);
  const onceki = s.sonIz || '';
  temiz.sonIz = iz;
  temiz.sonOzet = metin.slice(0, 300);

  if (!onceki) {
    // İlk kontrol: yalnızca başlangıç durumu kaydedilir, bildirim gitmez.
    temiz.ilkKayit = simdi;
  } else if (onceki !== iz) {
    temiz.sonDegisim = simdi;
    const eskiUzunluk = Number(String(onceki).split(':')[1] || 0);
    const fark = metin.length - eskiUzunluk;
    degisenler.push({
      ad: s.ad, url: s.url,
      fark: fark > 0 ? '+' + fark : String(fark),
      ozet: metin.slice(0, 300),
    });
  }
  yeniListe.push(temiz);
});

const gonderilecek = degisenler.length > 0;
let text = '';
let html = '';
const gun = new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long' });

if (gonderilecek) {
  const satirlar = ['🔍 Sayfa değişti (' + degisenler.length + ') — ' + gun];
  const parcalar = [];
  for (const d of degisenler) {
    satirlar.push('', '• ' + d.ad + ' (' + d.fark + ' karakter)', d.url, '  ' + d.ozet.slice(0, 200) + '…');
    parcalar.push('<h3>' + esc(d.ad) + ' <small>(' + esc(d.fark) + ' karakter)</small></h3>' +
      '<p><a href="' + esc(d.url) + '">' + esc(d.url) + '</a></p>' +
      '<blockquote style="color:#555">' + esc(d.ozet) + '…</blockquote>');
  }
  if (hatalar.length) satirlar.push('', '⚠️ ' + hatalar.join('\n⚠️ '));
  text = satirlar.join('\n');
  html = '<div style="font-family:system-ui,sans-serif;line-height:1.5"><h2>🔍 Sayfa değişti</h2>' +
    parcalar.join('') +
    (hatalar.length ? '<p style="color:#b00">⚠️ ' + esc(hatalar.join(' | ')) + '</p>' : '') + '</div>';
}

return [{ json: {
  gonderilecek, yazilsin: true, sayfalar: yeniListe,
  konu: '🔍 Takip ettiğiniz sayfa değişti (' + degisenler.length + ')',
  text, html,
  bilgi: gonderilecek ? degisenler.length + ' sayfa değişti.' : 'Değişiklik yok.' +
         (hatalar.length ? ' Sorunlu: ' + hatalar.join(' | ') : ''),
} }];

// Telegram kuruluysa değişiklik uyarısı oraya gider.
const j = $input.first().json;
if (!j.gonderilecek) return [];
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: j.text.slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE uyarı mail olarak gider (çift bildirim olmasın).
const j = $input.first().json;
if (!j.gonderilecek) return [];
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
return [{ json: { konu: j.konu, html: j.html } }];

// Dosyaya yalnızca sayfa listesi (güncel parmak izleriyle) yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { sayfalar: j.sayfalar } }];
